def components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            result.append((color, cells))
    return result


def normalized(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return frozenset((r - min_r, c - min_c) for r, c in cells)


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    objs = components(grid)

    # Find the long, one-cell-thick L marker: a full vertical leg meeting a
    # full horizontal leg at one corner. The L bounds the reference region.
    marker = None
    for color, cells in objs:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        for corner in ((r0, c0), (r0, c1), (r1, c0), (r1, c1)):
            cr, cc = corner
            vertical = {(r, cc) for r in range(r0, r1 + 1)}
            horizontal = {(cr, c) for c in range(c0, c1 + 1)}
            if vertical | horizontal == cells:
                marker = (color, (r0, r1, c0, c1))
                break
        if marker:
            break
    if marker is None:
        return out

    key_color, (r0, r1, c0, c1) = marker
    # The L's bounding box identifies the enclosed corner region; find two
    # translated copies of the same object, one inside and one outside it.
    shapes = {}
    for i, (color, cells) in enumerate(objs):
        if color == key_color:
            continue
        shape = normalized(cells)
        shapes.setdefault(shape, []).append((i, color, cells))

    for copies in shapes.values():
        inside = []
        outside = []
        for item in copies:
            _, _, cells = item
            fully_inside = all(r0 <= r <= r1 and c0 <= c <= c1 for r, c in cells)
            if fully_inside:
                inside.append(item)
            else:
                outside.append(item)
        if inside and outside:
            # Recolor the copy outside the L-bounded region to the marker color.
            _, _, target = outside[0]
            for r, c in target:
                out[r][c] = key_color
            return out
    return out


